-- feat-onboarding-trial : messages pendant l'Aero Endurance Test, au moment
-- opportun plutôt qu'un règlement à lire avant de pédaler.
--
-- * 0 s : position relevée de référence (15 s) ;
-- * 20 / 80 / 150 s : découverte guidée — surface frontale, vitesse
--   virtuelle, jauge d'efficacité aéro ;
-- * 240 s : 1 minute avant le défi ; 300 s : début du défi, XP à gagner ;
-- * 1 500 s : rappel « tiens ta position » existant, gardé.
--
-- Textes des nouvelles clés dans translations_json.live_comments (9 langues),
-- lu par les versions installées : jamais de clé brute affichée. Les
-- messages de l'XP (×2, ×3, réserve) sont déclenchés par l'app.

UPDATE public.training_sessions
SET live_comments = '[{"at": 0, "key": "trial_ah_lc_upright", "duration": 15}, {"at": 20, "key": "trial_ah_lc_area", "duration": 12}, {"at": 80, "key": "trial_ah_lc_speed", "duration": 12}, {"at": 150, "key": "trial_ah_lc_gauge", "duration": 12}, {"at": 240, "key": "trial_ah_lc_ready", "duration": 12}, {"at": 300, "key": "trial_ah_lc_start", "duration": 15}, {"at": 1500, "key": "trial_aero_hold_hint", "duration": 12}]'::jsonb,
    translations_json = jsonb_set(
      coalesce(translations_json, '{}'::jsonb),
      '{live_comments}',
      '{"trial_ah_lc_upright": {"en": "Sit upright. AeroX is setting your reference position.", "fr": "Reste relevé. AeroX enregistre ta position de référence.", "es": "Pedalea erguido. AeroX está fijando tu posición de referencia.", "pt": "Fique em posição alta. O AeroX está registrando sua posição de referência.", "it": "Resta in posizione alta. AeroX sta registrando la tua posizione di riferimento.", "de": "Fahr aufrecht. AeroX legt gerade deine Referenzposition fest.", "nl": "Blijf rechtop. AeroX legt je referentiepositie vast.", "ja": "上体を起こしてください。AeroXが基準姿勢を記録しています。", "tr": "Dik pozisyonda kal. AeroX referans pozisyonunu kaydediyor."}, "trial_ah_lc_area": {"en": "Now explore. Lean forward, tuck in, sit up again: watch your frontal area change live.", "fr": "À toi d''explorer. Penche-toi, rentre-toi, relève-toi : regarde ta surface frontale changer en direct.", "es": "Ahora explora. Inclínate, recógete, incorpórate: mira cómo cambia tu área frontal en directo.", "pt": "Agora explore. Incline-se, encolha-se, levante-se: veja sua área frontal mudar ao vivo.", "it": "Ora esplora. Piegati, raccogliti, rialzati: guarda la tua superficie frontale cambiare in diretta.", "de": "Jetzt entdecken. Beug dich vor, mach dich klein, richte dich auf: Sieh live, wie sich deine Stirnfläche ändert.", "nl": "Nu verkennen. Buig voorover, maak je klein, ga weer rechtop: zie je frontale oppervlakte live veranderen.", "ja": "さあ探索しよう。前傾し、体を小さくし、また起こして、前面投影面積の変化をリアルタイムで見よう。", "tr": "Şimdi keşfet. Öne eğil, küçül, tekrar doğrul: ön yüzey alanının canlı değiştiğini izle."}, "trial_ah_lc_speed": {"en": "Watch your virtual speed. At the same power, it rises as you get more aero.", "fr": "Regarde ta vitesse virtuelle. À puissance égale, elle monte quand tu es plus aéro.", "es": "Mira tu velocidad virtual. Con la misma potencia, sube cuanto más aero vas.", "pt": "Veja sua velocidade virtual. Com a mesma potência, ela sobe quando você fica mais aero.", "it": "Guarda la tua velocità virtuale. A parità di potenza, sale quando sei più aero.", "de": "Achte auf deine virtuelle Geschwindigkeit. Bei gleicher Leistung steigt sie, je aerodynamischer du bist.", "nl": "Kijk naar je virtuele snelheid. Bij hetzelfde vermogen stijgt die als je aerodynamischer zit.", "ja": "バーチャル速度を見よう。同じパワーでも、エアロになるほど速くなります。", "tr": "Sanal hızına bak. Aynı güçte, daha aero oldukça artar."}, "trial_ah_lc_gauge": {"en": "The gauge shows your aero efficiency. 0% upright, higher as your position gets more aerodynamic.", "fr": "La jauge montre ton efficacité aéro. 0 % relevé, de plus en plus haut à mesure que ta position devient aérodynamique.", "es": "El indicador muestra tu eficiencia aero. 0 % erguido, más alto cuanto más aerodinámica es tu posición.", "pt": "O medidor mostra sua eficiência aero. 0 % em posição alta, mais alto conforme sua posição fica mais aerodinâmica.", "it": "L''indicatore mostra la tua efficienza aero. 0% in posizione alta, più alto quanto più la posizione è aerodinamica.", "de": "Die Anzeige zeigt deine Aero-Effizienz. 0 % aufrecht, höher, je aerodynamischer deine Position wird.", "nl": "De meter toont je aero-efficiëntie. 0% rechtop, hoger naarmate je positie aerodynamischer wordt.", "ja": "ゲージはエアロ効率を示します。上体を起こすと0％、姿勢がエアロになるほど上がります。", "tr": "Gösterge aero verimliliğini gösterir. Dik pozisyonda %0, pozisyonun aerodinamikleştikçe yükselir."}, "trial_ah_lc_ready": {"en": "1 minute before the challenge. Find the aero position you can hold.", "fr": "1 minute avant le défi. Trouve la position aéro que tu peux tenir.", "es": "1 minuto para el reto. Encuentra la posición aero que puedas mantener.", "pt": "1 minuto para o desafio. Encontre a posição aero que você consegue manter.", "it": "1 minuto alla sfida. Trova la posizione aero che riesci a tenere.", "de": "Noch 1 Minute bis zur Challenge. Finde die Aero-Position, die du halten kannst.", "nl": "Nog 1 minuut tot de uitdaging. Zoek de aeropositie die je kunt volhouden.", "ja": "チャレンジまであと1分。キープできるエアロポジションを見つけよう。", "tr": "Meydan okumaya 1 dakika. Koruyabileceğin aero pozisyonunu bul."}, "trial_ah_lc_start": {"en": "Your challenge starts now. Stay aero to earn XP!", "fr": "Ton défi commence maintenant. Reste en aéro pour gagner des XP !", "es": "Tu reto empieza ahora. ¡Sigue en aero para ganar XP!", "pt": "Seu desafio começa agora. Fique em aero para ganhar XP!", "it": "La tua sfida inizia ora. Resta in aero per guadagnare XP!", "de": "Deine Challenge beginnt jetzt. Bleib in Aero-Position, um XP zu sammeln!", "nl": "Je uitdaging begint nu. Blijf aero om XP te verdienen!", "ja": "チャレンジ開始！エアロをキープしてXPを獲得しよう！", "tr": "Meydan okuman şimdi başlıyor. XP kazanmak için aero''da kal!"}}'::jsonb
    )
WHERE name = 'trial_aero_hold_session_name';
